mapper.select:
SELECT sms02_history_id                                         AS history_id
     , sms02_company_id                                         AS company_id
     , TO_CHAR(sms02_send_date, 'yyyy-mm-dd hh24:mi:ss')        AS send_date_str
     , sms02_content                                            AS content
     , sms02_note                                               AS note
  FROM sms02_history
 WHERE sms02_company_id = #{companyId}
   AND sms02_send_date BETWEEN #{startDate} AND #{closeDate}
   AND CONCAT(sms02_content) ILIKE #{searchText}
 ORDER BY sms02_send_date DESC
 LIMIT #{limit}
